  "summary": "The code suffers from high-risk performance bottlenecks due to synchronous-like shell execution and lacks basic architectural modularity. I have implemented a caching mechanism for git logs, secured the file serving logic, and introduced environment-based configuration to improve overall stability and maintainability.",
  "fixed_code": "const express = require('express');
const { execFile } = require('child_process');
const path = require('path');
const rateLimit = require('express-rate-limit');

const app = express();
const UPLOADS = path.resolve(__dirname, 'uploads');
const PORT = process.env.PORT || 3000;
const MIN_GIT_LOG = 1;
const MAX_GIT_LOG = 100;

let gitCache = { data: null, timestamp: 0 };
const CACHE_TTL = 60000;

const limiter = rateLimit({ windowMs: 60000, max: 50 });
app.use(limiter);

/**
 * Fetches recent git commits.
 */
app.get('/log', (req, res) => {
    const count = Number.parseInt(req.query.n, 10);
    if (!Number.isInteger(count) || count < MIN_GIT_LOG || count > MAX_GIT_LOG) {
        return res.status(400).json({ error: `n must be ${MIN_GIT_LOG}-${MAX_GIT_LOG}` });
    }

    const now = Date.now();
    if (gitCache.data && (now - gitCache.timestamp < CACHE_TTL)) {
        return res.json({ commits: gitCache.data.slice(0, count) });
    }

    execFile('git', ['log', '--oneline', '-n', String(MAX_GIT_LOG)], { timeout: 5000 }, (err, stdout) => {
        if (err) return res.status(500).json({ error: 'git failed' });
        gitCache.data = stdout.split('\n').filter(Boolean);
        gitCache.timestamp = Date.now();
        res.json({ commits: gitCache.data.slice(0, count) });
    });
});

/**
 * Serves files from uploads directory with path traversal protection.
 */
app.get('/files/:name', (req, res) => {
    const full = path.resolve(UPLOADS, req.params.name);
    const relative = path.relative(UPLOADS, full);
    if (relative.startsWith('..') || path.isAbsolute(relative) || !full.startsWith(UPLOADS + path.sep)) {
        return res.sendStatus(400);
    }
    res.sendFile(full);
});

app.listen(PORT, () => console.log(`Server running on port ${PORT}`));"
}
